const menuToggle=document.querySelector('.menu-toggle');const menu=document.querySelector('#menu');menuToggle.addEventListener('click',()=>{const open=menuToggle.getAttribute('aria-expanded')==='true';menuToggle.setAttribute('aria-expanded',String(!open));menu.classList.toggle('open',!open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menuToggle.setAttribute('aria-expanded','false');menu.classList.remove('open')}});
const slides=[{image:'movimento-muni.jpg',alt:'Campanha MUNI: movimento, pele e tecido esportivo verde',kicker:'SEU CORPO. SUA VIDA.',title:'Cuidar de você<br>é um <em>movimento.</em>',label:'Entre no universo MUNI',url:'/universo/'},{image:'higgsfield-nutrition.webp',alt:'Peras e uvas verdes em uma composição editorial de alimentação',kicker:'NUTRIÇÃO QUE ENCONTRA VOCÊ',title:'Mais sabor.<br><em>Mais você.</em>',label:'Explore a nutrição',url:'/nutricao/'},{image:'higgsfield-movement.webp',alt:'Campanha MUNI: roupa esportiva e toalha verde',kicker:'MOVIMENTO QUE CABE NA SUA VIDA',title:'Seu corpo.<br><em>Seu ritmo.</em>',label:'Explore os treinos',url:'/treinamento/'}];
document.querySelectorAll('[data-slide]').forEach(button=>button.addEventListener('click',()=>{const s=slides[Number(button.dataset.slide)];const image=document.querySelector('#campaign-image');image.src='/assets/'+s.image;image.alt=s.alt;document.querySelector('#campaign-kicker').textContent=s.kicker;document.querySelector('#campaign-title').innerHTML=s.title;const link=document.querySelector('#campaign-link');link.textContent=s.label;link.href=s.url;document.querySelectorAll('[data-slide]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))})}));
const gallery=[['muni-digital.jpg','Identidade digital MUNI em notebook','01 / CONEXÃO'],['higgsfield-objects.webp','Objetos conceituais com identidade MUNI','02 / CUIDADO'],['encontro-muni.jpg','Encontro na inauguração do Espaço MUNI','03 / ENCONTROS']];document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{const s=gallery[Number(button.dataset.gallery)];const image=document.querySelector('#gallery-image');image.src='/assets/'+s[0];image.alt=s[1];document.querySelector('#gallery-caption').textContent=s[2];document.querySelectorAll('[data-gallery]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))})}));
let interest='',format='';const names={nutricao:'Nutrição',treinamento:'Treinamento',integrado:'Nutrição + treinamento',presencial:'presencial em Jundiaí',online:'online'};function updateChoice(){const summary=document.querySelector('#choice-summary');if(!summary)return;summary.textContent=interest&&format?names[interest]+', '+names[format]+'.':interest?names[interest]+'. Agora, escolha seu formato.':format?'Atendimento '+names[format]+'. Escolha sua área.':'Escolha sua área de interesse e seu formato.';document.querySelector('#choice-detail').textContent=interest&&format?'Esse é seu ponto de partida. A equipe explica os atendimentos e a disponibilidade.':'Depois, converse com a equipe pelos canais da MUNI.';document.querySelectorAll('[data-interest]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.interest===interest)));document.querySelectorAll('[data-format]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.format===format)))}document.querySelectorAll('[data-interest]').forEach(b=>b.addEventListener('click',()=>{interest=b.dataset.interest;updateChoice()}));document.querySelectorAll('[data-format]').forEach(b=>b.addEventListener('click',()=>{format=b.dataset.format;updateChoice()}));const initial=new URLSearchParams(location.search).get('interesse');if(['nutricao','treinamento','integrado'].includes(initial)){interest=initial;updateChoice()}

// The supplied brand tile is the artwork; this layer only animates its placement.
(()=>{const sections=[...document.querySelectorAll('.living-pattern')];if(!sections.length)return;const reduce=matchMedia('(prefers-reduced-motion: reduce)');let enabled=!reduce.matches;let pending=0;const texture=new Image();texture.src='/assets/pattern-unit.png';const states=sections.map(section=>{const canvas=document.createElement('canvas');canvas.className='brand-canvas';canvas.setAttribute('aria-hidden','true');section.prepend(canvas);return{section,canvas,ctx:canvas.getContext('2d'),visible:false,width:0,height:0,x:-500,y:-500,tx:-500,ty:-500}});function schedule(){if(!pending)pending=requestAnimationFrame(draw)}function resize(s){const r=s.section.getBoundingClientRect();s.width=r.width;s.height=r.height;const d=Math.min(devicePixelRatio||1,1.5);s.canvas.width=Math.round(r.width*d);s.canvas.height=Math.round(r.height*d);s.ctx.setTransform(d,0,0,d,0,0);schedule()}function draw(){pending=0;if(!texture.complete||!texture.naturalWidth)return;let unsettled=false;states.forEach(s=>{if(!s.visible)return;const{ctx,width,height}=s;ctx.clearRect(0,0,width,height);s.x+=(s.tx-s.x)*.13;s.y+=(s.ty-s.y)*.13;unsettled ||= enabled&&(Math.abs(s.tx-s.x)+Math.abs(s.ty-s.y)>.3);const mobile=width<600,step=mobile?125:170,size=mobile?74:100;const drift=enabled?Math.sin((scrollY+s.section.offsetTop)*.0014)*16:0;for(let row=-1;row<Math.ceil(height/step)+1;row++){for(let col=-1;col<Math.ceil(width/step)+1;col++){let x=col*step+(row%2)*step/2+drift;let y=row*step+drift*.5;let angle=0,near=0;if(enabled&&s.tx>=0){const dx=x-s.x,dy=y-s.y,d=Math.hypot(dx,dy);near=Math.max(0,1-d/210);if(d>1){x+=dx/d*near*24;y+=dy/d*near*24}angle=near*.12*(dx<0?-1:1)}ctx.save();ctx.globalAlpha=.095+near*.13;ctx.translate(x,y);ctx.rotate(angle);ctx.drawImage(texture,-size/2,-size/2,size,size*texture.height/texture.width);ctx.restore()}}});if(unsettled)schedule()}const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{const s=states.find(x=>x.section===entry.target);s.visible=entry.isIntersecting;if(s.visible)resize(s)})},{rootMargin:'60px'});const resizer=new ResizeObserver(entries=>entries.forEach(entry=>{const s=states.find(x=>x.section===entry.target);if(s)resize(s)}));states.forEach(s=>{observer.observe(s.section);resizer.observe(s.section);s.section.addEventListener('pointermove',e=>{if(!enabled)return;const r=s.section.getBoundingClientRect();s.tx=e.clientX-r.left;s.ty=e.clientY-r.top;schedule()},{passive:true});s.section.addEventListener('pointerleave',()=>{s.tx=-500;s.ty=-500;schedule()},{passive:true})});addEventListener('scroll',()=>{if(enabled)schedule()},{passive:true});texture.onload=schedule;const controls=document.querySelectorAll('.motion-toggle');function sync(){controls.forEach(b=>{b.textContent=enabled?'Pausar fundo':'Ativar fundo';b.setAttribute('aria-pressed',String(enabled))});states.forEach(s=>{s.tx=s.x=-500;s.ty=s.y=-500});schedule()}controls.forEach(b=>b.addEventListener('click',()=>{enabled=!enabled;sync()}));reduce.addEventListener('change',()=>{enabled=!reduce.matches;sync()});sync()})();
